"""Transient collision wire preview generated by the Source model exporter."""
import bpy
from bpy.app.handlers import persistent
from mathutils import Vector

_handle = None
_scene = None
_asset = None
_lines = []


@persistent
def clear(*_):
    global _handle, _scene, _asset, _lines
    if _handle is not None:
        bpy.types.SpaceView3D.draw_handler_remove(_handle, 'WINDOW')
    _handle = None
    _scene = None
    _asset = None
    _lines = []
    redraw()


def redraw():
    for window in bpy.context.window_manager.windows:
        for area in window.screen.areas:
            if area.type == 'VIEW_3D':
                area.tag_redraw()


def geometry(context, asset):
    from . import model_smd, model_lifecycle, profiles
    from .export_scope import Scope

    if not profiles.is_source(asset.get('wl_model_profile', '')):
        raise ValueError('Collision preview currently supports Source 1 assets')
    state = asset.wavelength_model
    if state.collision_mode == 'NONE':
        raise ValueError('Choose a collision mode first')
    scope = Scope(context.scene, context.view_layer)
    if state.collision_mode == 'OBJECT':
        if not state.collision or state.collision.name not in context.scene.objects:
            raise ValueError('Choose an existing collision mesh')
        if not scope.includes(state.collision):
            raise ValueError('Enable the collision mesh for export')
    triangles = []
    model_smd.export(asset, context.scene, {}, scope=scope, collision_triangles=triangles)
    root = state.origin
    entity = model_lifecycle.entity_for(context.object)
    pose = entity.matrix_world if entity and entity.get('wl_custom_model') == asset else root.matrix_world
    unit = root.get('wl_unit_meters', asset['wl_model_unit_meters'])
    lines = []
    for triangle in triangles:
        world = [pose @ (Vector(point) * unit) for point in triangle]
        for first, second in ((0, 1), (1, 2), (2, 0)):
            lines.extend((tuple(world[first]), tuple(world[second])))
    return lines


def draw():
    from . import workspace, model_io
    context = bpy.context
    if context.scene != _scene or not workspace.active(context) or model_io.active_asset(context) != _asset:
        return
    import gpu
    from gpu_extras.batch import batch_for_shader
    shader = gpu.shader.from_builtin('UNIFORM_COLOR')
    depth = gpu.state.depth_test_get()
    try:
        gpu.state.depth_test_set('NONE')
        shader.bind()
        shader.uniform_float('color', (0.2, 1.0, 0.35, 1.0))
        batch_for_shader(shader, 'LINES', {'pos': _lines}).draw(shader)
    finally:
        gpu.state.depth_test_set(depth)


def show(context, asset):
    global _handle, _scene, _asset, _lines
    lines = geometry(context, asset)
    clear()
    _scene, _asset, _lines = context.scene, asset, lines
    _handle = bpy.types.SpaceView3D.draw_handler_add(draw, (), 'WINDOW', 'POST_VIEW')
    redraw()


def register():
    for handlers in (bpy.app.handlers.load_pre, bpy.app.handlers.undo_pre, bpy.app.handlers.redo_pre):
        handlers.append(clear)


def unregister():
    clear()
    for handlers in (bpy.app.handlers.load_pre, bpy.app.handlers.undo_pre, bpy.app.handlers.redo_pre):
        if clear in handlers:
            handlers.remove(clear)
